// Shape Anthropic output + Vapi metadata into the app callback payload.
const end = $('Vapi Call Ended').first().json.body.message;
const meta = (end.call && end.call.metadata) || {};
const raw = $json.content && $json.content[0] ? $json.content[0].text : '{}';
let parsed = {};
try { parsed = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) {}
const score = Math.max(0, Math.min(100, Math.round(Number(parsed.score) || 0)));
const status = score >= 75 ? 'QUALIFIED' : score >= 45 ? 'FOLLOW_UP' : 'DISQUALIFIED';
const reason = end.endedReason || '';
const answered = !/no-answer|did-not-answer|busy|failed|voicemail/i.test(reason);
return [{ json: {
  callbackUrl: meta.callbackUrl,
  event: 'call.completed',
  data: {
    attemptId: meta.attemptId,
    answered,
    transcript: (end.artifact && end.artifact.transcript) || end.transcript || '',
    recordingUrl: (end.artifact && end.artifact.recordingUrl) || end.recordingUrl || '',
    durationSeconds: end.durationSeconds,
    score,
    status,
    summary: parsed
  }
} }];
